local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["zone:tirisfal"] = {n="提瑞斯法林地",s="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色十字军所包围，是一个充满危险的国度，拥有自由意志的亡灵在此艰难求生。",h="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色...",kw={"阿加曼德","巴尼尔","布瑞尔","丧钟镇","被遗忘者","林地","洛丹伦","血色十字军","希尔瓦娜斯","提瑞斯法","幽暗城"},ang={["class:Priest"]="法奥之墓——白银之手创始人阿隆索斯·法奥大主教的陵墓——等具有历史意义的神圣之地也坐落于此，但它们已被死亡扭曲，并在狂热者和暗影牧师之间反复争夺。",["faction:Alliance"]="对于联盟的幸存国家来说，提瑞斯法是洛丹伦陷落的悲剧纪念碑，充满了曾经信仰相同的兄弟姐妹们那遭到亵渎的墓穴。",["faction:Horde"]="提瑞斯法是部落在东部王国北部的关键堡垒，它巩固了与被遗忘者的外交关系，同时抵御人类极端分子和天灾军团的侵袭。",["race:Undead"]="这是你双重的祖居之地：你生前所建立的王国，以及你在死后作为被遗忘者、在希尔瓦娜斯女士统治下必须誓死捍卫的危险避难所。"},sec={{t="暮色中的土地",b="提瑞斯法林地曾是人类文明繁荣的摇篮，但在巫妖王的瘟疫诅咒下已然凋零。阳光难得穿透昏暗的迷雾，给枯萎的树林、荒废的南瓜地以及冰冷的海岸丘陵笼罩上了一层病态的苍白。尽管阿加曼德磨坊和巴尼尔农场等古老的农庄遗迹尚存，但它们曾经的主人大多已被扫入乱葬岗，或是化作了不安的亡者。尽管饱受摧残，但这片土地依然展现出一种黑暗的韧性，以布瑞尔这样的城镇和丧钟镇那与世隔绝的避难所为基点，让新觉醒的被遗忘者学习如何忍受他们的第二人生。"},{t="双线战争",b="虽然希尔瓦娜斯女士声称她从地下的洛丹伦废墟统治着该地区，但被遗忘者依然在四面受敌。残余的天灾爪牙依然在空谷、田野和破败的墓穴中横行，完全效忠于诺森德的冰封王座。在东方，狂热的血色十字军将提瑞斯法北部作为其主要堡垒，并以血色修道院为大本营。他们疯狂地致力于消灭每一个亡灵生物——无论是生者还是死者——他们的哨站和巡逻队不断地对被遗忘者的侦察兵和平民旅客进行游击作战。"},{t="远古的余音",b="在人类王国加冕第一位君主很久之前，这片林地就承载着古老的遗产。高等精灵流亡者曾试图在此定居，但深埋于地下的暗影能量使他们发疯，促使他们向北迁徙。在随后的几个世纪里，被称为提瑞斯法议会的秘密人类法师组织选择了这些阴影笼罩的林地，以赋予孤独的守护者力量，守护艾泽拉斯免受恶魔入侵。"}},faq={{q="为什么天空是绿色的，土地在腐烂？",a="在第三次战争期间，阿尔萨斯王子和天灾军团向洛丹伦王国散布了亡灵瘟疫。这种魔法毒素不仅毒害了居民，还毒害了土壤、树木和水源，使林地陷入了永恒、诡异且病态的腐烂状态。",al={"为什么提瑞斯法枯萎了","提瑞斯法发生了什么","为什么提瑞斯法正在死亡"}},{q="这里的被遗忘者和天灾军团有什么区别？",a="被遗忘者是在海加尔山之战后摆脱了巫妖王心灵控制的亡灵，他们选择追随希尔瓦娜斯·风行者女士，拥有自己的自由意志。而那些在农场和废墟中游荡的天灾军团，依然是受制于巫妖王命令的无心智奴隶。",al={"被遗忘者与天灾军团","为什么僵尸攻击亡灵","所有的亡灵都是邪恶的吗"}},{q="那些攻击旅客的红甲士兵是谁？",a="他们属于血色十字军，这是一个由前白银之手骑士团成员和幸存者组成的极端分裂组织。他们坚信所有亡灵都是不可救赎的畸形生物，必须用刀剑和火焰来净化。他们怀着狂热的仇恨，处决了包括无心智的爪牙和拥有自由意志的被遗忘者在内的所有亡灵。",al={"血色十字军","红色人类","修道院的人类"}},{q="提瑞斯法这个名字从何而来？",a="这个名字比任何人类王国都要古老，其真正的起源已湮没在历史中。它最广为人知的是源于提瑞斯法议会，这是一个秘密的法师组织，赋予了守护者保护艾泽拉斯免受恶魔侵扰的力量。",al={"提瑞斯法的含义","提瑞斯法的起源"}},{q="新觉醒的被遗忘者从哪里开始他们的旅程？",a="新觉醒的被遗忘者从丧钟镇内的灰影墓穴中走出，这是一个位于提瑞斯法西南部的隐秘城镇。在那里，管理者和执行者会评估复活的死者是否具备服务黑暗女王所需的理智和忠诚。",al={"亡灵新手区域","丧钟镇在哪里","被遗忘者新手出生地"}},{q="旅客如何离开提瑞斯法前往其他大陆？",a="布瑞尔以南的山坡上，就在洛丹伦废墟外，坐落着一座巨大的地精经营的飞艇塔。这些飞艇提供穿越海洋的定期直达航线，分别前往卡利姆多的奥格瑞玛和荆棘谷的格罗姆高营地。",al={"提瑞斯法飞艇","如何前往奥格瑞玛","如何前往荆棘谷"}}},fx={["6c272224"]={q="提瑞斯法林地是什么地方？",a="提瑞斯法林地是被遗忘者位于洛丹伦北部海岸的故土。这里曾是一个强盛的人类王国富饶而宁静的核心地带，却在第三次战争期间遭天灾军团的亡灵瘟疫蹂躏。如今，受污染的树林和永无止境的绿色阴霾笼罩着群山，洛丹伦首都的废墟映衬其间，周围则盘踞着敌对的狂热分子、野化猛兽和残存的亡灵。",al={"提瑞斯法是什么地方","介绍一下提瑞斯法林地","提瑞斯法地区背景"}},["342b65f9"]={q="这里一直都是亡灵的土地吗？",a="不是。数千年来，提瑞斯法一直是人类文明的摇篮，也是洛丹伦王国繁荣的中心。在泰瑞纳斯·米奈希尔国王统治下，宁静的农庄、兴旺的磨坊和小村落蓬勃发展。第三次战争期间，阿尔萨斯王子和诅咒神教带着瘟疫席卷而来，这一时代就此惨烈终结，居民被变成亡灵奴隶，直到希尔瓦娜斯将他们解放。",al={"提瑞斯法一直都是亡灵之地吗","以前这里住着谁","瘟疫之前的提瑞斯法"}},["4790468d"]={q="谁生活在提瑞斯法林地，或由谁统治这里？",a="被遗忘者以幽暗城为据点，在希尔瓦娜斯·风行者女王的统治下宣称拥有提瑞斯法林地。然而，他们的控制权始终受到挑战。狂热的血色十字军在东北方掌控着防御工事和宏伟的修道院；毫无心智的天灾军团则在废弃农场间游荡。在东部边境的亡灵壁垒，被遗忘者与银色黎明并肩协作，遏制瘟疫之地的恐怖威胁。",al={"谁统治提瑞斯法","谁控制提瑞斯法林地","提瑞斯法的阵营"}},["97ffdb73"]={q="提瑞斯法林地危险吗？",a="极其危险。离开被遗忘者据点的围墙后，你会遭遇毫无心智的天灾军团残部、凶残的豺狼人、巨型蛛类，以及受瘟疫污染的凶猛野兽。更可怕的是血色十字军的狂热分子，他们一发现亡灵就会将其处决。遥远的东边是西瘟疫之地，那里的怪物比提瑞斯法林地的任何生物都要致命，足以将毫无防备的人撕成碎片。",al={"提瑞斯法有多危险","提瑞斯法的威胁","这里安全吗"}},["30e6283a"]={q="谁在布瑞尔当家？",a="执政官塞弗伦负责布瑞尔的民政管理，统筹城镇重建和日常生计。军事权力和战术行动，尤其是对附近血色十字军的战役，则由执行官塞加德指挥。",al={"布瑞尔的首领","谁领导布瑞尔","布瑞尔的负责人"}},["3fc3649e"]={q="执政官塞弗伦向谁负责？",a="塞弗伦效忠于黑暗女王希尔瓦娜斯·风行者。作为布瑞尔的执政官，他代表被遗忘者王室在此地区行使民政权力，并与幽暗城的王室执行官及皇家药剂师协会直接协作。",al={"塞弗伦的上司","塞弗伦向谁汇报","布瑞尔的领导关系"}},["381a9b46"]={q="女妖之王在哪里？",a="希尔瓦娜斯·风行者女士居住在幽暗城的皇家区，那里位于首都废墟深处、布瑞尔正南方。她在王座厅指挥被遗忘者对抗天灾军团和血色十字军。",al={"希尔瓦娜斯在哪里","寻找希尔瓦娜斯","女妖之王的位置"}},e7993821={q="布瑞尔是什么地方？",a="布瑞尔是提瑞斯法林地中部主要的被遗忘者城镇，坐落在首都以北的十字路口沿线。这里曾是巴罗夫家族领地上的一处生者聚居地，第三次战争后被重建，为新近苏醒的亡灵提供休憩、交易和集结之所，然后再踏上前往世界各地的旅途。",al={"布瑞尔介绍","布瑞尔是什么样的城镇","布瑞尔背景"}},["529e09c8"]={q="以前这里有人类居住吗？",a="有。布瑞尔曾是洛丹伦王国境内一处宁静的人类社区。克尔苏加德策划的早期瘟疫实验以这里为中心，导致大量居民丧生，并留下巨大的公共墓穴——那时阿尔萨斯王子还没有前来调查。",al={"以前有人类住在布瑞尔吗","布瑞尔的生者历史","以前住在布瑞尔的人"}},["7b7ff5e2"]={q="恐惧之末旅店是什么地方？",a="恐惧之末旅店是布瑞尔的中央集会厅和旅店。这里提供庇护、令人作呕的酒饮，以及在外面阴森林地中奔波后的喘息之机。在阴暗的角落里，被遗忘者会关押俘虏的敌人——比如血色十字军的狂热分子——以供药剂师进行邪恶的药剂试验。",al={"恐惧之末旅店","布瑞尔旅店","恐惧之末是什么地方"}},["0d8014ee"]={q="阿加曼德磨坊是怎么回事？",a="阿加曼德磨坊曾是提瑞斯法林地最富有、产量最高的农庄，以面粉和谷物闻名。瘟疫袭来时，整座庄园沦陷，惨遭屠戮。如今，这里已成为一片腐朽的废墟，点缀着风车，遍布残留的天灾亡灵。",al={"阿加曼德磨坊背景","阿加曼德磨坊发生了什么","阿加曼德磨坊"}},["001d4abe"]={q="阿加曼德家族是什么人？",a="阿加曼德家族是一个富有的贵族人类世家，他们开辟了广阔的磨坊，并在提瑞斯法各地拥有产业，包括布瑞尔。第三次战争期间，财富也未能拯救他们；家族惨遭天灾军团灭门，复活的族长们至今仍在庄园里游荡。",al={"阿加曼德家族","谁住在阿加曼德磨坊"}},eeb96a2c={q="它们也是亡灵，为什么还要攻击我们？",a="阿加曼德磨坊里的亡灵从未恢复自由意志。与摆脱了巫妖王精神控制的被遗忘者不同，这些生物仍是毫无心智的天灾奴仆，被迫摧毁任何闯入其领地的生者或反叛亡灵。",al={"阿加曼德家族为什么攻击我们","阿加曼德的亡灵为何敌对","为什么要和其他亡灵战斗"}},a357af07={q="离开提瑞斯法之后，接下来该去哪里？",a="大多数被遗忘者会向南穿过山口，前往银松森林，协助巩固南部边境，并对抗达拉然的特工和腐皮豺狼人。此外，布瑞尔南面的飞艇可以载你前往奥格瑞玛，或跨海抵达格罗姆高营地。",al={"离开提瑞斯法后去哪里","提瑞斯法之后的下一个地区","提瑞斯法林地之后"}},["50336b90"]={q="幽暗城是什么地方？",a="幽暗城是被遗忘者庞大的地下首都，建在破碎的洛丹伦废墟之下古老的下水道、墓穴和地下墓室中。它既是希尔瓦娜斯女王的要塞，也是被遗忘者在艾泽拉斯各地行动的指挥中心。",al={"幽暗城是什么地方","幽暗城背景","关于幽暗城"}},ddddba9f={q="接下来要去银松森林吗？",a="是的。沿着提瑞斯法林地南面的道路前行，就能直接进入银松森林。那里是你继续为被遗忘者效力的自然去处，你将在那里对抗洛丹伦南部边境日益加剧的威胁。",al={"接下来去银松森林","接下来去银松森林吗","银松森林边境"}},["789ead4d"]={q="我是怎么来到提瑞斯法林地的？",a="如果你是新近复生的被遗忘者，那么你在洛丹伦沦陷于天灾军团之手时死去，并被埋葬在这里。巫妖王的控制被打破后，你恢复了自由意志，并从丧钟镇这处僻静山谷的坟墓中爬了出来。如果你属于部落的其他种族，很可能是乘坐飞艇来到这里的。飞艇塔位于布瑞尔和幽暗城之间，可将这片被污染的土地与奥格瑞玛和格罗姆高营地直接连通。",al={"我是怎么来到这里的","怎么来到提瑞斯法林地","我是怎么到这里的"}},["89135166"]={q="我在提瑞斯法林地应该做什么？",a="你的目标是帮助被遗忘者巩固他们对洛丹伦这片受污染腹地脆弱的控制。从丧钟镇的墓穴出发，前往布瑞尔镇，你必须清除盘踞在废弃农场的无意识天灾军团，铲除从北方逼近的血色十字军狂热信徒，并猎杀在腐朽树林中游荡的染疫野兽。这样做能证明你对希尔瓦娜斯女王的价值，也能让你为她在旧城废墟下日益壮大的王国效力做好准备。",al={"我在这里该做什么","为什么在提瑞斯法","我在这里的目标是什么"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="幽暗城",s="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，也是部落在东部王国北部的关键据点。",h="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，...",kw={"apothecarium","阿尔萨斯","被遗忘者","洛丹伦","天灾军团","希尔瓦娜斯","泰瑞纳斯","提瑞斯法","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="作为部落在东部王国的主要立足点，幽暗城保障了直达杜隆塔尔和格罗姆高营地的飞艇航线。",["race:Human"]="在你覆灭的祖国土地下，坐落着洛丹伦皇家墓穴的阴森扭曲之物，那里被你曾经族人的行尸走肉所占据。",["race:Orc"]="就在这些地牢的深处，传奇大酋长奥格瑞姆·毁灭之锤曾被洛丹伦联盟囚禁，随后才完成了他那场历史性的逃脱。",["race:Undead"]="幽暗城是你的主权避难所和家园，是在打破巫妖王对你心智的铁腕控制后，由你们亲手开凿而成的。"},sec={{t="从皇家墓穴到天灾要塞",b="在瘟疫席卷洛丹伦很久之前，皇宫下方的地下墓穴、地牢和下水道就被统称为幽暗城。这里关押着贵族的陵墓、王国最深处的监狱——前任大酋长奥格瑞姆·毁灭之锤在逃脱前曾被关押于此——以及王国最贫困的居民。当阿尔萨斯·米奈希尔在20 ADP谋杀泰瑞纳斯国王并摧毁首都时，这位王子命令他的亡灵仆从挖掘并扩建这些地下通道，将其建成了一座天灾统治下的坚固要塞。"},{t="被遗忘者的崛起",b="天灾军团从未见证过他们黑暗之都的完工。在海加尔山之战后，当巫妖王的实力减弱时，希尔瓦娜斯·风行者摆脱了蜂巢思维的控制，并带走了数千名亡灵。她诱使阿尔萨斯陷入埋伏，并将他赶回了诺森德。在经历了针对天灾残党、恐惧魔王和人类抵抗军的激烈三方内战后，希尔瓦娜斯占据了这座未完工的地下墓穴。她将她的人民命名为被遗忘者，并监督了数年的劳动，完成了这座庞大的地下城市。"},{t="被诅咒的建筑",b="幽暗城呈同心圆布局，分为若干功能区。其核心是贸易区，通过巨大的升降梯与上方的废墟连接。环绕在它周围的是军事区、盗贼区、法师区和充满毒气的药剂师区，皇家药剂师学会就在那里利用满是绿色粘液的运河酿造致命的瘟疫。更深处是皇家区，希尔瓦娜斯女王与她的恐惧魔王指挥官瓦里玛萨斯在此坐镇，周围守卫着无数高大的憎恶。"}},faq={{q="在亡灵占领之前，幽暗城是什么样子的？",a="在洛丹伦皇宫下方，坐落着古代人类王室的墓穴，以及城市的地牢建筑群和巨大的下水道网络。这里曾关押过战俘，包括奥格瑞姆·毁灭之锤，还有生活在地下阴影中的赤贫平民。在洗劫首都后，阿尔萨斯王子开始将这些地下墓穴改造成天灾要塞，随后被希尔瓦娜斯夺取。",al={"幽暗城起源","幽暗城最初是什么","洛丹伦下水道历史"}},{q="为什么城市建在地下而不是地面上？",a="洛丹伦的地面城市在第三次战争中完全沦为废墟，使其难以抵御血色十字军、天灾军团和联盟幸存者的攻击。地下隧道提供了天然的防御工事、阻塞点和隐秘性，使得被遗忘者能够完成天灾军团最初的建设，并在不为人知的情况下繁荣发展。",al={"为什么住地下","为什么不重建洛丹伦","为什么幽暗城在废墟之下"}},{q="谁统治着幽暗城？",a="这座城市由希尔瓦娜斯·风行者女王，即女妖之王和被遗忘者女王统治。她从皇家区进行管辖，并由被遗忘者皇家卫兵和她征服的恐惧魔王副官瓦里玛萨斯守卫。",al={"幽暗城的领袖是谁","幽暗城统治者","谁管理幽暗城"}},{q="废墟上方的泰瑞纳斯国王纪念碑是做什么用的？",a="在城市主要升降梯的上方，矗立着一座为被杀害的泰瑞纳斯·米奈希尔二世国王建造的石质纪念碑。里面并没有他的遗体，因为他的尸体在克尔苏加德复活时被火化，骨灰也被丢弃了。幸存的联盟人类在废墟中勇敢地雕刻了这座纪念碑，以便让人们铭记洛丹伦最后一位真正国王的记忆。",al={"泰瑞纳斯国王陵墓","洛丹伦王座大厅之墓","谁建造了幽暗城上方的墓穴"}},{q="洛丹伦王座大厅里那些奇怪的声音是什么？",a="在幽暗城升降梯上方的废墟王座大厅中，过去的幽灵回声依然挥之不去。站在中央的访客可以听到模糊的幻听：阿尔萨斯归来时庆祝的钟声和落下的玫瑰花瓣，先知麦迪文的警告，以及泰瑞纳斯国王与他弑父逆子之间最后的对话。",al={"王座大厅的幽灵声","王座大厅的低语","洛丹伦王座大厅的声音"}},{q="为什么被遗忘者允许其他部落成员进入这里？",a="被遗忘者与萨尔大酋长的部落结成了权宜联盟以求生存，因为他们周围环绕着充满敌意的血色狂热者和天灾军团。尽管有生命的部落种族会觉得这里的毒雾和炼金河流令人窒息，但为了促进外交和军事联系，使者和旅行者仍被允许进入。",al={"为什么兽人在幽暗城","幽暗城的部落","为什么幽暗城是部落的一部分"}}},fx={a590d153={q="幽暗城是什么？",a="幽暗城是被遗忘者的地下首都，直接建在提瑞斯法林地中破碎的旧城废墟下方。它由古老的皇家墓穴、下水道和地下墓穴开凿而成。在内战期间，阿尔萨斯王子曾将其扩建为天灾军团的要塞，后来希尔瓦娜斯·风行者女王和她麾下的叛离亡灵夺取了这里。如今，它是自由意志亡灵的坚固庇护所，城中纵横着有毒污泥，并由守卫严密防范所有生者闯入。",al={"幽暗城是什么","介绍幽暗城","幽暗城背景"}},c51b16b2={q="洛丹伦的老国王遭遇了什么？",a="泰瑞纳斯·米奈希尔二世国王在这座城市正上方的王座厅里被自己的儿子阿尔萨斯王子杀害。阿尔萨斯从诺森德归来时已被符文剑霜之哀伤腐化，他杀死了父亲，并将天灾军团释放到王国各处。后来，死亡骑士盗走了泰瑞纳斯的骨灰，用以复活克尔苏加德，只留下纪念碑，以及你如今仍能在废弃王座附近看到的干涸血迹。",al={"泰瑞纳斯国王的结局","泰瑞纳斯国王遭遇了什么","谁杀了泰瑞纳斯国王"}},c11144c7={q="阿尔萨斯是谁？",a="阿尔萨斯·米奈希尔是洛丹伦的王储，也是一位声名卓著的白银之手圣骑士。为了阻止席卷故土的亡灵瘟疫，他的征讨逐渐变得冷酷而偏执。在诺森德，他夺取了被诅咒的符文剑霜之哀伤，灵魂被其吞噬，成为巫妖王令人畏惧的勇士。他回到故乡后屠杀了父亲，夷平了洛丹伦，最终又返回北方，与冰封王座融为一体。",al={"阿尔萨斯是谁","阿尔萨斯王子的背景","阿尔萨斯·米奈希尔"}},["7f6bbd49"]={q="希尔瓦娜斯·风行者是谁？",a="希尔瓦娜斯·风行者女王曾是银月城英勇的游侠将军，在第三次战争期间抵御天灾军团，保卫奎尔萨拉斯。她战死后，阿尔萨斯从她的尸体中抽出灵魂，将她扭曲成女妖加以折磨。巫妖王的控制减弱后，她挣脱束缚，夺回肉身，并集结其他独立的亡灵，建立了被遗忘者。如今，她在皇家区统治着他们，成为女妖之王。",al={"女妖之王是谁","希尔瓦娜斯背景","希尔瓦娜斯是谁"}},["2a8de90f"]={q="希尔瓦娜斯为什么被称为黑暗女王？",a="被遗忘者尊称希尔瓦娜斯为黑暗女王，因为她将他们从巫妖王无意识的奴役中解放出来，并在艾泽拉斯其他地方都想将他们彻底灭绝时给予他们庇护。这个称号与女妖之王的头衔一样受人敬仰，既体现了她掌控死亡的幽暗力量，也体现了她的亡灵臣民对她坚定不移的忠诚。",al={"为什么叫黑暗女王","希尔瓦娜斯的黑暗女王头衔","黑暗女王的含义"}},["84f18f47"]={q="被遗忘者为什么属于部落？",a="被敌对的血色十字军、穷追不舍的天灾军团和复仇心切的联盟残部包围，被遗忘者无法独自在洛丹伦生存。希尔瓦娜斯女王越过大海联系了大酋长萨尔，缔结了一项务实的互利同盟。部落因此在东部王国获得了至关重要的军事据点，而被遗忘者则在为生存而战的过程中获得了必需的援军和政治合法性。",al={"被遗忘者为何加入部落","亡灵加入部落","被遗忘者、部落与联盟"}},["71200045"]={q="天灾军团是什么？它们还在附近吗？",a="天灾军团是由燃烧军团创造、受巫妖王统治的庞大无意识亡灵军队，巫妖王在诺森德指挥它们。尽管被遗忘者夺回了幽暗城和提瑞斯法林地，天灾军团仍是迫在眉睫的致命威胁。在克尔苏加德的指挥下，它们的军团仍盘踞在附近的瘟疫之地，并侵扰林地各处废弃的农庄和墓穴。",al={"天灾军团还在附近吗","天灾军团是什么","洛丹伦的天灾军团"}},["501548ab"]={q="巫妖王现在在哪里？",a="巫妖王居住在遥远的诺森德冰封荒原之上的冰封王座。瘟疫之地内战结束后，阿尔萨斯王子逃离洛丹伦，去保护力量日渐衰弱的主人。他登上冰川，与巫妖王的精魂合二为一，成为一个令人恐惧的存在。从那座极地堡垒中，他冰冷的目光仍注视着艾泽拉斯。",al={"巫妖王在哪里","巫妖王的位置","阿尔萨斯现在在哪里"}},["4cc7f971"]={q="血色十字军是什么人？",a="血色十字军是一个由洛丹伦防线废墟中诞生的人类狂热组织。他们被对亡灵的正义仇恨蒙蔽双眼，无法区分无意识的天灾军团与拥有自由意志的被遗忘者。他们认为任何沾染亡灵气息的人，以及任何容忍他们的生者异乡人，都是只配被送上火刑架的邪恶怪物。他们在提瑞斯法林地的主要据点是血色修道院。",al={"血色十字军是什么人","血色十字军成员","血色十字军背景"}},["271820ed"]={q="幽暗城危险吗？",a="那里极其危险，尤其是对生者而言。炼金废料和有毒污泥的沟渠流经城市街道，毒气弥漫在宽阔的大厅中，让血肉之躯难以安全呼吸。铺砌街区的下方是遭到侵扰的下水道，更深处则是隐秘的实验场所，那里每天都有人策划黑暗炼金实验和冷酷的暗杀行动。",al={"幽暗城安全吗","幽暗城的危险","幽暗城有哪些危险"}},["2539a3c3"]={q="我是怎么来到幽暗城的？",a="作为被遗忘者，你在丧钟镇死而复生，并在提瑞斯法林地证明忠诚之后，自然会沿着道路经过布瑞尔，来到旧城破碎的废墟下方。如果你来自卡利姆多或遥远的地方，很可能是乘坐停靠在首都外飞艇塔的部落飞艇抵达，或是跋涉穿过受污染的乡野。幽暗城是部落在洛丹伦北部的主要据点，在古老王宫的地下墓穴下方为你提供庇护和使命。",al={"我是怎么来到这里的","怎么到达幽暗城","如何前往幽暗城"}},b63c4cf2={q="我在幽暗城应该做什么？",a="你来到这里，是为了帮助被遗忘者，并集结部落的力量，对抗洛丹伦周边的威胁。在城内层层环绕的城区中，你可以向职业训练师请教、购买补给，并咨询皇家药剂师协会的黑暗研究者。除了经营自己的专业，你还要接受希尔瓦娜斯·风行者女王及其副官的任务。被遗忘者要在多条战线上作战：清剿无意识天灾军团的残余势力，击退狂热的血色十字军，并为拥有自由意志的亡灵守住栖身之地。",al={"我在这里做什么","我在幽暗城该做什么","我为什么在这里"}}},fp="9,304,36.483.0,20.506.0,26.483.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="安戈洛环形山",s="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",h="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",kw={"魔暴龙","火羽山","众神之地","拉卡里","马绍尔营地","能量水晶","托尔瓦·寻路者","安戈洛","安戈洛环形山"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们研究安戈洛与世隔绝的生态系统，并采集其肥沃的土壤来培育魔草，试图理解维持这片火山口的纯净、未受驯化的生命力。",["faction:Alliance"]="联盟的博物学家聚集在马绍尔营地的威利德·马绍尔和J.D.科利身边，争分夺秒地破译泰坦水晶塔，同时保护达纳苏斯的研究人员采集土壤样本。",["faction:Horde"]="部落冒险者经常经由塔纳利斯到达这里，对抗传说中的魔暴龙以考验自己的实力，并协助雷霆崖的草药师利用安戈洛的原始泥土培育魔草。",["profession:Herbalism"]="盆地中丰富的水分滋养了稀有的植物，使其成为卡利姆多为数不多的几个盲目草、梦叶草和黄金参在火山斜坡上与火焰花共同繁茂的地方之一。",["profession:Mining"]="陡峭的环形山壁和火羽山的岩架上遍布着秘银矿脉和富瑟银矿脉，使该地区成为获取高端矿石的首选目的地。"},sec={{t="众神之地",b="安戈洛环形山夹在广阔的沙漠之间，违背了卡利姆多南部的地理特征。记载流沙之战的古老暗夜精灵文献指出，虫族其拉曾被阻挡在环形山的边缘，无法进入他们口中所谓的“众神之地”。学者们推测，在塑造卡利姆多期间，这座火山口曾作为泰坦的试验场或古代居所。石塔耸立在山脊上，发出阵阵嗡鸣，蓝色、红色、绿色和黄色的水晶体从原始的土地中破土而出。"},{t="野蛮的生态系统",b="安戈洛环形山内没有城市、城镇或土著类人生物社会。相反，生命以一种未受驯化的原始状态繁衍。顶级的魔暴龙在恐惧小道的平原上潜行，捕食性的血瓣花在沼泽地中发动攻击，软泥怪在拉卡里的焦油坑中爬行。在环形山的中心，火羽山拔地而起，这座活跃的火山峰上挤满了由名为“烈焰奔腾者”的实体所领导的敌对火元素。对于探险家和剥皮者来说，这片盆地拥有无与伦比的自然财富——包括令人垂涎的魔暴龙皮——前提是你能在食物链中幸存下来。"},{t="马绍尔营地",b="在环形山内的文明存在几乎仅限于马绍尔营地，这是一个位于北部悬崖上的高处营地。在威利德·马绍尔的带领下，一支由科学家、博物学家和寻宝者组成的探险队曾试图整理这片盆地的宝藏，却遭到了怪物般的野生动物的重创，被迫退守高地。如今，该营地已成为勇敢的旅行者们的前哨站，他们在那里研究环形山神秘的能量水晶、绘制火山活动图，并警惕地监视着从南部山脊入侵的希利苏斯虫群。"}},faq={{q="如何进入安戈洛环形山？",a="旅行者可以通过通向环形山壁的自然坡道进入：一条位于塔纳利斯西南角靠近灌木谷的地方，另一条从东北部的希利苏斯进入。虽然鲁莽的冒险者有时会从悬崖上跳下，但如果没有魔法协助，坠落是致命的。北部的马绍尔营地提供前往加基森和塞纳里奥要塞的飞行点。",al={"如何进入安戈洛","安戈洛入口","如何前往安戈洛环形山"}},{q="彩色能量水晶有什么用？",a="丛林地面上散布着红色、蓝色、绿色和黄色的能量水晶。在马绍尔营地的侏儒研究员J.D.科利的指导下，探险者可以破译在北部、东部和西部水晶塔上使用这些水晶的说明。在相应的水晶塔上组合特定的颜色，可以利用潜在的泰坦能量来制作防御或恢复性的护符。",al={"安戈洛水晶","安戈洛红蓝绿黄水晶","能量水晶塔"}},{q="为什么安戈洛被沙漠包围却依然葱郁？",a="学者们认为安戈洛非自然的活力是人为的，源于塑造世界的泰坦。泰坦导管、来自火羽山的温暖火山地热活动，以及古老的能量流滋养了一个与世隔绝、超速发展的生态系统，使其能够抵御邻近的塔纳利斯和希利苏斯的干旱环境。",al={"为什么安戈洛是丛林","安戈洛与沙漠的关联","安戈洛如何生长植物"}},{q="为什么其拉虫人称这里为“众神之地”？",a="根据从流沙之战翻译来的石板记载，虫群在环形山的入口处停止了前进。翻译此记录的地质学家拉克斯班将这个名字与泰坦曾居住在环形山的理论联系了起来，并推测阿曼苏尔本人是否曾经守护过众神之地。",al={"众神之地含义","其拉虫人与安戈洛","为什么希利苏斯虫群无法占领安戈洛"}},{q="安戈洛的泥土有什么用？",a="在环形山盆地各处都有肥沃、强效的泥土堆。采集后，这种泥土可以与瑟利斯种子放入常青袋中，以培育魔草，这是一种受到雷霆崖、达纳苏斯和塞纳里奥议会的研究人员热切追捧的神秘草药。",al={"安戈洛土壤样本","安戈洛的泥土有什么用","魔草土壤"}},{q="这里有类人生物定居点或地下城吗？",a="安戈洛环形山拥有一个供58到60级左右玩家进入的地下城——塑造者之台，但没有原生的类人生物社会。唯一长久存在的定居点是马绍尔营地，这是一个位于北缘的小型探险前哨站。除了隐居的猎人或迷路的探险者外，火山口的其他地方完全处于原始状态。",al={"安戈洛地下城","谁住在安戈洛","安戈洛的类人生物"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="哀嚎洞穴",s="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地下世界。如今洞穴内满是扭曲的野兽和堕落的信徒，他们被一种深层、非自然的梦魇所腐蚀。",h="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地...",kw={"变异","尖牙德鲁伊","翡翠梦魇","安娜科德拉","考布莱恩","皮萨斯","瑟芬迪斯","甜水绿洲","穆坦努斯","纳拉雷克斯","永生者"},ang={["class:Druid"]="对于塞纳里奥传统的德鲁伊和走牛头人道路的修行者来说，这些洞穴是一个关于翡翠梦境危险的悲剧警示，也是净化他们堕落兄弟——尖牙德鲁伊的庄严职责。",["race:NightElf"]="纳拉雷克斯曾是暗夜精灵德鲁伊中备受尊敬的人物，他被翡翠梦魇腐化的悲剧，对他远在海对岸的族人来说是一场痛苦的灾难。",["race:Tauren"]="扭曲的水域威胁着维持贫瘠之地生命的脆弱绿洲，使得净化泉水对莫高雷和十字路口的部落人民至关重要。"},sec={{t="高尚愿景的腐化",b="暗夜精灵德鲁伊纳拉雷克斯最初发现了这个广阔的水系，并制定了一个雄心勃勃的计划：通过开启一条直通翡翠梦境的通道，他可以将原始的生命精华引入地下泉水，将干涸的贫瘠之地变回繁茂的绿洲天堂。在洞穴深处，在忠诚侍僧的守护下，纳拉雷克斯进入了与梦境的交流中。可悲的是，这位德鲁伊沉睡的意识触碰到的并非纯净的生命力，而是翡翠梦魇。那肆虐的腐化瞬间攫住了他，将他那本意良好的通道变成了一个向地下水道倾泻毒液与疯狂的阀门。"},{t="尖牙德鲁伊",b="当梦魇的黑暗能量从纳拉雷克斯无助的身躯中辐射开来时，他的学生们屈服于疯狂。他们背弃了塞纳里奥议会的宁静智慧，组建了狂热的尖牙德鲁伊。这些教派领袖——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯——化身为爬行动物，与其对抗洞穴的变异，不如说他们拥抱了这种毒性突变。他们积极保护沉睡的主人免受任何外界干扰，坚信这种扭曲的生长才是大自然的真正进化。"},{t="梦魇的实体化",b="打破尖牙德鲁伊的控制并不能自动拯救纳拉雷克斯。当他剩余未受腐化的门徒在Dreamer's Rock开始仪式，试图轻唤他从恍惚中醒来时，这位沉睡精灵的潜意识剧烈挣扎，排出了他内心深处最可怕的恐惧。随之喷薄而出的生物——一只巨大、扭曲的鱼人，名叫吞噬者穆坦努斯——便是纳拉雷克斯最可怕梦魇的物理化身。只有消灭这个怪物，通往梦魇的渠道才能被切断，纳拉雷克斯才能苏醒、化为禽鸟形态，从这被污染的洞穴中飞离。"}},faq={{q="为什么叫哀嚎洞穴？",a="洞穴因隧道中传出的凄凉哀嚎声而得名。这些声音是由于地下蒸汽喷口和高压风流穿过石灰岩狭窄裂隙时自然产生的。",al={"为什么叫哀嚎洞穴","名称由来","为什么会哀嚎"}},{q="洞穴里的野兽为何会变得“变异”？",a="当纳拉雷克斯陷入翡翠梦魇的控制时，被污染的梦境能量直接渗入了地下泉水。饮用并生活在这些被污染的水域中，导致自然的迅猛龙、鳄鱼和毒蛇变成了非自然的“变异”物种。",al={"变异腐化","迅猛龙为什么变异","变异野兽起源"}},{q="谁是尖牙德鲁伊？",a="他们曾是纳拉雷克斯虔诚的暗夜精灵和牛头人侍僧。随着他一同被梦魇腐化，他们的心智崩溃，将德鲁伊技艺扭曲为对毒蛇和毒液的崇拜，并采用了考布莱恩、皮萨斯和安娜科德拉这样的称号。",al={"尖牙德鲁伊","尖牙德鲁伊背景","瑟芬迪斯是谁"}},{q="为什么最终首领是一只名叫穆坦努斯的巨型鱼人？",a="穆坦努斯是在尝试唤醒纳拉雷克斯的过程中出现的。随着仪式的展开，它的本质及其与沉睡德鲁伊的联系便会揭晓。",al={"穆坦努斯为什么是鱼人","穆坦努斯是什么","最终首领背景"}},{q="击败穆坦努斯后会发生什么？",a="门徒唤醒纳拉雷克斯的尝试在战斗结束后继续进行。仪式结束时，这位德鲁伊的命运便会揭晓。",al={"唤醒纳拉雷克斯","纳拉雷克斯的结局","纳拉雷克斯发生了什么"}},{q="谁住在洞穴入口上方的洞穴里？",a="在洞穴那形似骷髅的岩石眼眶里，驻扎着塞纳里奥议会的忠诚成员，包括纳尔帕克和厄布鲁。他们寻求勇敢的旅者收集变异皮，并在腐化彻底吞噬贫瘠之地前将其净化。",al={"入口上方的洞穴","蛇骷髅眼眶非玩家角色","纳尔帕克和厄布鲁是谁"}}},fx={["8502642f"]={q="这里由谁掌管？",a="纳拉雷克斯被困在洞穴深处，陷入受腐化影响的沉睡之中，而洞穴的日常事务则由尖牙德鲁伊掌管。他们由瑟芬迪斯领导。瑟芬迪斯曾是纳拉雷克斯最出色的学生，如今却召集了扭曲的同胞，企图将这片土地改造成他们自己的畸变乐园。考布莱恩、皮萨斯和安娜科德拉等其他尖牙领主也与他并肩行事。",al={"谁领导哀嚎洞穴","哀嚎洞穴的首领","哀嚎洞穴的首领是谁"}},["32be29c8"]={q="什么是翡翠梦境？它与这座洞穴有什么联系？",a="翡翠梦境是一个广阔的灵界，映照着未经触碰、野性未驯的艾泽拉斯。它由绿龙军团守护，德鲁伊可以进入其中。纳拉雷克斯相信，自己能够将梦境中纯净且具有复苏之力的能量引入哀嚎洞穴的地下含水层，让贫瘠之地重新长满茂盛的植物。然而，当他尝试汲取这股力量时，却被翡翠梦魇缠住，将扭曲的自然投射到了现实中的洞穴里。",al={"翡翠梦境的联系","哀嚎洞穴与翡翠梦境","纳拉雷克斯与翡翠梦境"}},["38e519c2"]={q="为什么大家都这么担心这个地方？",a="洞穴中的地下泉水滋养着主要绿洲，为贫瘠之地各处的生命提供水源。如果翡翠梦魇的污秽继续不受遏制地渗入水道，侵蚀洞穴动植物的扭曲变异与疯狂便可能蔓延至整个地区，让这片土地化为一场挥之不去的噩梦。",al={"为什么担心哀嚎洞穴","哀嚎洞穴对贫瘠之地的威胁","哀嚎洞穴有多危险"}},["81917ac6"]={q="我是怎么来到哀嚎洞穴的？",a="你从十字路口向南前往甜水绿洲，沿途听说贫瘠之地出现了怪异野兽，受污染的水也在不断扩散。绿意葱茏的植被与科卡尔半人马营地后方，岩石中凿出了一座巨大的骷髅形洞穴。你可能是响应雷霆崖的求援，或是为了棘齿城地精想要的奇异精华，也可能受到骷髅眼窝上方营地中门徒的吸引。穿过蜿蜒的裂隙和嘶鸣的地下间歇泉后，你便深入了下方呻吟般的幽暗深处。",al={"我是怎么到这里的","怎么去哀嚎洞穴","我是从哪里来的"}},["28a012f3"]={q="我在哀嚎洞穴里应该做什么？",a="你来到这里，是为了净化这处地下泉水遭受的腐化。暗夜精灵德鲁伊纳拉雷克斯试图让贫瘠之地重焕生机，却陷入了噩梦般的沉睡，洞穴中的生物因此变得扭曲，他的门徒也沦为充满毒性的尖牙德鲁伊。你必须追猎四位尖牙领主——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯，瓦解他们的控制，然后帮助幸存的门徒唤醒纳拉雷克斯，以免他狂热的噩梦彻底吞噬绿洲。",al={"我在这里的目标是什么","我为什么在哀嚎洞穴","我在这里做什么"}},["3386ab3f"]={q="哀嚎洞穴是什么？",a="哀嚎洞穴是一片广阔的地下洞穴网络，位于贫瘠之地干旱的土地下方，靠近甜水绿洲。洞穴中的天然地下泉水在大地深处流淌数里，为散布在这片区域的稀有地表绿洲供水。暗夜精灵德鲁伊纳拉雷克斯发现了这里，原本打算将其作为一项宏大自然复苏计划的核心。然而，一场悲剧性的灾难降临洞中的德鲁伊后，这里反而成了危险腐化的中心。",al={"哀嚎洞穴是什么","哀嚎洞穴概况","关于哀嚎洞穴"}},e070a543={q="那里住着什么？",a="洞穴中充斥着异变的野生生物和叛离的德鲁伊。纳拉雷克斯被腐化的追随者——尖牙德鲁伊——与变异蛇类、软泥怪、迅猛龙和鳄鱼共同占据了洞穴隧道。副本入口外的潮湿通道中潜伏着野兽、软泥怪，甚至还有流亡者；而被腐化的德鲁伊则守卫着内室，保护他们沉睡的主人。",al={"哀嚎洞穴里有什么人","哀嚎洞穴的生物","哀嚎洞穴的居民"}},["49d47201"]={q="部落为什么派我来这里？",a="当地野兽的奇异变异，以及从甜水绿洲涌出的邪恶能量，威胁着整个贫瘠之地。部落和雷霆崖的塞纳里奥德鲁伊无法容忍失控的黑暗力量在十字路口附近污染土地和水道。你被派来调查此事，铲除尖牙德鲁伊的叛变首领，并帮助平息日益扩大的危险。",al={"我为什么在哀嚎洞穴","部落在哀嚎洞穴的任务","为什么派我去哀嚎洞穴"}},d445bb78={q="这是贫瘠之地更大危机的一部分吗？",a="是的。这些洞穴下方的地下水道为贫瘠之地各处地表绿洲供水。梦魇之力对洞穴水源的腐化已经开始向周围蔓延，导致迅猛龙和鳄鱼等野生生物发生变异，并使甜水绿洲成为奇异变异生物的滋生地。",al={"贫瘠之地的绿洲问题","贫瘠之地的变异腐化","哀嚎洞穴是否影响贫瘠之地"}},["038fd1cf"]={q="变异生物正在扩散到洞穴外吗？",a="它们已经扩散出来了。地下泉水直接流入甜水绿洲等地表绿洲，将异常生长和变异生物带到了开阔的草原上。你可以从洞外水域钓到变异鱼等奇异生物，而且具有攻击性的变异掠食者也越来越频繁地袭击往返于绿洲和十字路口的旅人。",al={"变异生物正在扩散吗","贫瘠之地的变异野兽","洞外的变异鱼"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="战歌峡谷",s="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双方都在突袭对方的据点以夺取其旗帜。",h="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双...",kw={"战歌峡谷","战场","战歌氏族","银翼要塞","战歌伐木场","旗帜","木材","灰谷","葛罗·地狱吼"},ang={["faction:Alliance"]="联盟士兵在这里为他们的暗夜精灵盟友而战，他们的神圣森林正因战歌氏族的斧头而一棵接一棵地倒下。",["faction:Horde"]="每一根离开战歌伐木场的原木都能在卡利姆多的某个地方筑起一道部落城墙；守住峡谷就是维持部落的建设。",["race:NightElf"]="这些树林见证了卡多雷足迹一万年。每一个被赶出峡谷的兽人都意味着收复了一片灰谷。",["race:Orc"]="战歌氏族是葛罗·地狱吼的直属部队，峡谷是他的战士们依然赢得名声的地方，他们手持斧头对抗着银翼要塞。"},sec={{t="木材与鲜血",b="部落用木材在卡利姆多建立了新家园，而其中大部分木材都来自灰谷。自部落登陆以来，葛罗·地狱吼的战士——战歌氏族就一直在砍伐这片森林。他们位于峡谷尽头的战歌伐木场为部落的营地和城墙提供了补给。对于暗夜精灵来说，每一棵被砍伐的树木都伤害了他们守护了一万年的森林，他们也没有忘记葛罗的战士曾在这片树林中杀死了塞纳留斯。"},{t="先遣骑兵与哨兵",b="部落在这里的战士是战歌氏族，由贫瘠之地北缘的莫尔杉营地提供补给，凯尔姆·哈古斯在那里负责他们的武装和补给。与他们对抗的是银翼要塞的银翼要塞，这是一群发誓要将所有入侵者赶出灰谷的暗夜精灵战士，由银翼树林的艾蒂尔·月火负责补给。双方的盟友都涌向峡谷：矮人和人类站在银翼要塞一边，牛头人、巨魔和被遗忘者站在战歌氏族一边。"},{t="争夺战旗",b="双方在峡谷的一端各拥有一座据点，部落是战歌伐木场，暗夜精灵是银翼要塞，并且双方都将各自的战旗存放在那里。这场战斗是一场突袭竞赛：战士们冲入敌方的据点，夺取其旗帜并飞奔回自己的据点，同时防守者会追击他们。每一面带回家的旗帜都是对敌人自尊心的一次打击，夺取旗帜最多的一方将获得当天的胜利。"}},faq={{q="什么是战歌峡谷？",a="战歌峡谷是位于灰谷和贫瘠之地之间的一片森林峡谷中的战场。部落的战歌氏族和暗夜精灵的银翼要塞在那里为部落在灰谷的采伐活动而战，双方都在努力夺取对方的旗帜。",al={"什么是战歌峡谷","战歌峡谷战场","战歌峡谷"}},{q="部落为什么要参加战歌峡谷的战斗？",a="部落需要灰谷的木材来建造和维持其在卡利姆多的家园。战歌氏族在峡谷的伐木场是其主要来源之一，战歌氏族负责保卫它，以便部落的营地和城墙能够不断建立。",al={"部落争夺战歌峡谷","兽人为什么要砍伐灰谷","战歌氏族的目的"}},{q="暗夜精灵为什么要参加战歌峡谷的战斗？",a="对于暗夜精灵来说，灰谷是他们守护了一万年的神圣森林，而战歌氏族曾经在那里杀死了半神塞纳留斯。银翼要塞奋力阻止采伐并将兽人赶出他们的树林，而联盟的其他成员也与他们站在一起。",al={"联盟争夺战歌峡谷","哨兵为什么要战斗","银翼要塞的目的"}},{q="战歌氏族是谁？",a="战歌氏族是部落在战歌峡谷的战士，来自曾经由葛罗·地狱吼领导的战歌氏族。他们由位于贫瘠之地北部的莫尔杉营地提供补给，凯尔姆·哈古斯在那里为他们提供装备。",al={"战歌氏族","战歌氏族战士","凯尔姆·哈古斯"}},{q="银翼要塞是谁？",a="银翼要塞是银翼要塞的暗夜精灵战士，发誓要将部落赶出灰谷。银翼树林的艾蒂尔·月火为在峡谷中与他们并肩作战的联盟勇士提供补给。",al={"银翼要塞","艾蒂尔·月火"}},{q="如何在战歌峡谷的战斗中获胜？",a="双方在各自的据点中各持有一面旗帜。战士们突袭敌方的基地，夺取其旗帜并将其带回自己的基地，同时保卫自己的旗帜，带回最多旗帜的一方获胜。",al={"战歌峡谷目标","战歌峡谷夺旗","如何赢得战歌峡谷"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="西瘟疫之地",s="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上展开了绝望的抗争。",h="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上...",kw={"安多哈尔","亡灵壁垒","凯尔达隆","大熔炉","寒风营地","壁炉谷","玛登霍尔德城堡","通灵学院","乌瑟尔之墓","西瘟疫之地"},ang={["class:Paladin"]="洛丹伦被亵渎的田野是对圣洁战士的严峻考验，这里既有通往乌瑟尔之墓的朝圣之路，也有针对通灵学院和壁炉谷腐化狂热者的正义之战。",["faction:Alliance"]="寒风营地是联盟的前哨驻地，指挥官阿斯兰·斯托瓦尔在那里指挥部队干扰瘟疫大熔炉，并为洛丹伦陨落的城市复仇。",["faction:Horde"]="亡灵壁垒标志着被遗忘者主权的前线；从这里，部落向东推进，以消灭天灾指挥官，并对抗沿脆弱侧翼活动的血色十字军狂热者。",["profession:Herbalism"]="挥之不去的污染使得该地区成为少数几种罕见且危险的植物，如瘟疫花和阿尔萨斯之泪，能够在受瘟疫影响的松树林中扎根的地方之一。"},sec={{t="洛丹伦的粮仓",b="在第三次战争之前，这片土地是一条从提瑞斯法林地向东延伸至达隆米尔湖的青翠农田走廊。壁炉谷通过玛登霍尔德城堡进行北部管理，而广阔的安多哈尔城镇则负责整个王国的粮食储存和出口。这一关键的农业地位使得该地区成为了克尔苏加德的主要目标。通过直接在安多哈尔的粮食运输中引入亡灵瘟疫，The Cult of the Damned将洛丹伦的生命源泉变成了它的毁灭之源。"},{t="处于围困中的土地",b="为了永久污染这片土地，天灾军团在最大的几个农业区竖起了四座巨大的瘟疫大熔炉：费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场。今天，可怕的熔炉领主们守护着这些有害的大缸，向大气中喷射毒雾。周围的树木因肿瘤般的生长而扭曲，被瘟疫感染的野生动物在灌木丛中横行。在达隆米尔湖的凯尔达隆下方，黑暗院长加丁在通灵学院内训练死灵法师，加剧了亡灵的威胁。"},{t="分裂的阵营",b="尽管天灾军团无处不在，几个阵营仍在此保持着艰难的立足点。血色十字军控制着北部的壁炉谷要塞，以狂热的态度清洗任何他们认为被玷污的事物。在南部，联盟部队以寒风营地为基地，而被遗忘者则在亡灵壁垒防御着他们的边界。中立的银色黎明负责调解并指挥对抗亡灵大熔炉的战斗，他们援助两个阵营的勇士，并守护着乌瑟尔之墓——这是该地区最后一片真正神圣的土地。"}},faq={{q="为什么瘟疫对该地区的打击如此严重？",a="安多哈尔是洛丹伦北部的农业运输枢纽。克尔苏加德蓄意针对该地区的供应，感染了粮仓，并在四个主要农场安装了巨大的瘟疫大熔炉，以便通过全国的粮食运输迅速传播亡灵瘟疫。",al={"西瘟疫之地为何受瘟疫侵袭","安多哈尔发生了什么","为何此处有大熔炉"}},{q="谁控制着北部的壁炉谷？",a="壁炉谷及其要塞玛登霍尔德城堡由血色十字军统治。虽然最初是洛丹伦的地区行政中心，但这群狂热者现在会处决任何接近他们边界的外来者，对所有非十字军成员都持怀疑态度。",al={"壁炉谷的阵营","谁住在玛登霍尔德城堡","壁炉谷友好吗"}},{q="联盟和部落玩家在哪里可以找到安全的哨所？",a="联盟在靠近奥特兰克山脉的南部边界维护着寒风营地，提供飞行管理员和银色黎明盟友。部落则从提瑞斯法林地进入，在西部边界的亡灵壁垒开展行动。",al={"飞行点在哪里","西瘟疫之地的部落营地","西瘟疫之地的联盟营地"}},{q="农田里的瘟疫大熔炉有什么用途？",a="这些大熔炉由诅咒神教在费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场竖立，持续向空气和土壤中喷射瘟疫蒸汽。银色黎明的特工会招募冒险者去击杀熔炉领主，并对这些有毒的混合物进行反向工程。",al={"大熔炉是什么","大熔炉的用途","费尔斯通大熔炉"}},{q="什么是通灵学院，它位于何处？",a="通灵学院是一所由天灾军团和诅咒神教经营的地下死灵法术学院。它隐藏在凯尔达隆的废墟之下，那是一座位于达隆米尔湖东南水域的岛屿要塞。",al={"通灵学院的位置","通灵学院在哪里","凯尔达隆地下城"}},{q="西瘟疫之地有任何未被腐蚀的地方吗？",a="位于该地区南缘悔恨岭上的乌瑟尔之墓依然完全神圣，未受瘟疫影响。它是为陨落的高阶统帅乌瑟尔和失落的白银之手骑士团而立的神圣纪念碑。",al={"西瘟疫之地的圣地","乌瑟尔之墓干净吗","乌瑟尔之墓安全吗"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="西部荒野",s="西部荒野的农场毫无防护，迪菲亚潜行者控制着大片乡野。这片土地曾是暴风城的粮仓，如今却失去了王室的支持和军队的驻守，处境艰难。",h="西部荒野的农场毫无防护，迪菲亚潜行者控制着大片乡野。这片土地曾是暴风城的粮仓，如今却失去了王室的支持和军队的驻守，处境艰难。",kw={"死亡矿井","迪菲亚","收割傀儡","民兵","月溪镇","萨丁","哨兵岭","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="身为潜行者，你会发现一场暗战遍布西部荒野，SI:7的间谍在这里对抗迪菲亚潜行者中熟悉街头门道的斥候、盗贼和刺客。",["faction:Alliance"]="身为联盟的旅人，你能看到人民军如何守住哨兵岭。没有这支队伍，迪菲亚潜行者就会控制通往艾尔文森林的南部要道。",["profession:Cooking"]="身为厨师，你可以了解萨丁农场陷入困境的农户如何靠当地肉质粗硬的野兽维生，又如何教旅人烹制杂味炖肉。",["race:Human"]="身为人类，你能从西部荒野看到暴风城政治的腐朽。那些在尘土中忍饥挨饿的农民，曾辛勤劳作供养贵族，如今却被他们抛弃。"},sec={{t="被遗弃的土地",b="西部荒野的牧场和麦田曾养活了暴风城王国。Second War过后，王国财政日渐拮据，统治者也忽视了这片领土。暴风城将资源调往别处，撤走了驻军。土地就此荒芜。\n\n如今，荒芜的牧场、猛烈的海风、失控的收割傀儡和河爪豺狼人，让少数仍留在这里的农户艰难求生。"},{t="兄弟会的崛起",b="迪菲亚潜行者的到来加速了西部荒野的衰败。这些匪徒戴着红色面罩，追随一位乡间无人知晓其姓名的首领。他们将西部荒野变成据点，焚烧农田，向土壤撒盐，还占据了废弃的矿井。\n\n兄弟会盘踞在已成鬼镇的月溪镇，虽无统治之名，却掌控着大部分乡野。"},{t="人民民兵",b="贵族对西部荒野的困境置之不理，当地居民只得自行保卫家园。在哨兵岭，格里安·斯托曼组建了人民军，这支志愿部队坚守防线，抵御豺狼人和匪徒。暴风城既不派遣正规军，也不提供补给。\n\n这支民兵队依靠四处游历的冒险者击退迪菲亚潜行者，保护仅存的农场。"},{t="红色面罩下的石匠",b="艾德温·范克里夫领导着兄弟会。他曾是主持重建暴风城的公会首领，但贵族拒绝支付石匠们的工钱，随后的暴乱让他们被逐出城。他们来到西部荒野，戴上了红色面罩。如今焚烧农田的匪徒，正是当年亲手筑起王都城墙的工匠。"},{t="死亡矿井的阴谋",b="在月溪镇地下，艾德温·范克里夫将亡命之徒、地精和叛逃者聚集在死亡矿井废弃的金矿坑道里。兄弟会正在那里建造一艘庞大的铁甲战舰。他们打算让它沿海岸航行，炮轰暴风城。"}},faq={{q="为什么西部荒野有这么多荒废的农场？",a="驻军开销变得过于高昂后，暴风城撤走了军队，让西部荒野失去了保护。迪菲亚潜行者随后占据了大片乡野，赶走农户，焚烧农田，还改写了机械收割看守的程序，将它们变成致命的哨兵。",al={"荒废的农场","西部荒野为何衰落","为何荒芜"}},{q="为什么暴风城不派兵援助西部荒野？",a="王国的国库捉襟见肘，贵族优先应对其他地区的威胁。宫廷中的暗中操纵也悄然夺走了西部荒野本应得到的关注和补给，让居民只能自行保卫家园。",al={"为何没有暴风城军队","卫兵在哪里","暴风城的援助"}},{q="什么是人民民兵？",a="格里安·斯托曼在哨兵岭组建了人民军，保卫西部荒野。王室没有派兵前来，农民和定居者便联合起来，对抗迪菲亚潜行者和河爪豺狼人。",al={"人民民兵","哨兵岭民兵","格里安·斯托曼军队"}},{q="谁在西部荒野领导迪菲亚潜行者？",a="艾德温·范克里夫曾是石匠行会的会长，如今领导着迪菲亚潜行者。他曾主持暴风城的重建，后来，一场激烈的工钱纠纷以暴乱告终，他便带领工人来到西部荒野，将他们武装起来。",al={"迪菲亚首领","谁领导迪菲亚","范克里夫"}},{q="月溪镇里隐藏着什么？",a="月溪镇一座不起眼的谷仓下，藏着死亡矿井的入口。迪菲亚潜行者将这座废弃金矿改造成地下堡垒和造船厂，用于对暴风城的战争。",al={"月溪镇的秘密","死亡矿井里有什么","月溪镇矿井"}},{q="为什么机械稻草人会攻击人？",a="效忠迪菲亚潜行者的地精技师夺取了机械收割看守。这些机械原本用来照料庄稼、驱赶害虫。他们将其改装，用来巡逻田野，杀死闯入者。",al={"收割傀儡攻击","收割看守者","邪恶的稻草人"}}},fx={cd1e134e={q="西部荒野是什么地方？",a="西部荒野是暴风城王国西部饱受风吹的领土，位于艾尔文森林以西，向南延伸至海岸。这里曾是王国富饶的粮仓，起伏的丘陵和广阔的牧场养育了世世代代的暴风城居民。如今，由于王室疏于照管，又遭战乱蹂躏，这里已沦为荒芜的尘土平原、破败的农庄和亡命之徒的地盘。",al={"这是什么区域","西部荒野介绍","西部荒野背景"}},["44cadea7"]={q="这里为什么如此荒凉？",a="干旱、疏于治理和匪患相互叠加，使乡间人去地空。第二次战争后，暴风城将兵力集中到别处，让当地农庄失去了防卫。迪菲亚潜行者崛起后，他们驱赶农民，焚烧庄稼，还向田地撒盐。没有王室驻军保护，大多数居民不是逃离，就是饿死。",al={"西部荒野为何荒芜","为何如此荒凉","这里为何无人"}},["1a97e791"]={q="西部荒野一直都这么贫穷吗？",a="完全不是。世世代代以来，西部荒野都是暴风城引以为傲的农业腹地，以金色的麦田、肥沃的土壤，以及詹戈洛德和死亡矿井等储量丰富的金矿闻名。在战争与内乱使这里变得荒芜之前，这里的粮食供养着都城，矿产则充实着王室的宝库。",al={"西部荒野是否一直贫穷","西部荒野过去是否富裕","西部荒野的过去"}},["1d4a9481"]={q="迪菲亚潜行者是什么组织？",a="迪菲亚潜行者是一个庞大的犯罪组织，成员包括叛乱的石匠、盗贼、强盗和流亡者。在艾德温·范克里夫的领导下，他们占据了西部荒野废弃的农田与矿井，对暴风城王国发动了一场残酷的暗战，决意为拖欠的报酬和他们认定的背叛讨回公道。",al={"迪菲亚是谁","迪菲亚潜行者是什么组织","这些匪徒是谁"}},b6953315={q="迪菲亚为什么戴着红色面罩？",a="红色面罩是迪菲亚潜行者的标志，而面罩的材质代表着成员的等级。红色丝质面罩是较高阶成员的身份标识；哨兵瑞尔要求冒险者收集这些面罩，作为击杀他们的凭证。",al={"为何戴红色面罩","迪菲亚红色面罩","红色面罩的含义"}},["908b4fe1"]={q="迪菲亚在西部荒野想要什么？",a="他们将西部荒野视为自己独立掌控的据点和集结之地。通过控制金矿、夺取粮食补给并驱逐效忠王国的农民，他们得以避开暴风城的直接监视，秘密扩充兵力、制造机械，同时图谋颠覆王国。",al={"迪菲亚想要什么","迪菲亚在西部荒野的目标","迪菲亚为何在西部荒野"}},d384bc2d={q="为什么派我来西部荒野？",a="你被指引到这里，是因为暴风城的正规军拒绝或无力向西部荒野派兵，使这片领土濒临彻底落入匪徒之手的境地。艾尔文的官员将有能力的冒险者引向西方，支援那些苦苦挣扎、急需援助的当地居民。",al={"为何来到西部荒野","谁派我来西部荒野","为何派我来这里"}},d59f010f={q="格里安·斯托曼是谁？",a="格里安·斯托曼是白银之手的圣骑士，也是西部荒野本地人。他在第三次战争期间于洛丹伦作战，返乡后却发现故土已被匪徒占据，暴风城的军队也早已撤离。于是，他召集当地的守卫者，在哨兵岭建立了人民军。",al={"斯托曼是谁","格里安·斯托曼","谁领导哨兵岭"}},af1c3ddb={q="格里安·斯托曼真的掌管着西部荒野吗？",a="实际上，是的。尽管暴风城的少年国王在法理上拥有西部荒野，王室在这里却几乎毫无实权。斯托曼和他驻扎在哨兵岭的志愿民兵，是这片领土上仅存的、仍能履行防卫和执法职责的力量。",al={"谁统治西部荒野","斯托曼是否是领袖","谁在掌权"}},c01912f7={q="石匠行会遭遇了什么？",a="在会长艾德温·范克里夫的领导下，石匠行会在第一次战争后耗费数年重建暴风城。工程完工后，贵族却拒绝支付约定的报酬。和平请愿无果后，公会被强行解散，引发了愤怒的暴乱，石匠们也因此被迫流亡。",al={"石匠遭遇了什么","石匠行会的故事","石匠们是谁"}},ec2fd06e={q="暴风城真的拒绝付钱给石匠吗？",a="是的。贵族为扩大在其他地方的军事远征积累了惊人的债务，使王国濒临破产。在宫廷阴谋和贵族傲慢的影响下，贵族们只肯为浩大的工程支付区区小钱，断然拒绝按契约付清报酬。",al={"暴风城是否欺骗了石匠","贵族为何不付钱","石匠报酬纠纷"}},cf60f690={q="西部荒野为什么有这么多豺狼人？",a="河爪豺狼人越过边境迁徙而来，趁暴风城士兵缺席之机占据这里。更糟的是，迪菲亚潜行者主动雇用他们充当打手，将他们部署在各处丘陵和平原，伏击旅人，侵扰尚存的农庄。",al={"豺狼人为何在这里","西部荒野的河爪豺狼人","丹努文豺狼人"}},e40fa3bd={q="月溪镇是什么地方？",a="月溪镇曾是西部荒野南部最主要的集市和矿业城镇。它坐落在死亡矿井的古老入口上方，后来被迪菲亚潜行者彻底占领并清空，如今他们利用镇上空置的建筑，守卫地下据点的外围。",al={"月溪镇是什么地方","月溪镇背景","月溪镇介绍"}},["46f1c864"]={q="对迪菲亚的调查会通向何处？",a="你的调查揭露了这个组织藏在月溪镇下方死亡矿井中的秘密核心。在地下洞穴深处，艾德温·范克里夫正监督建造一艘巨大的铁甲战舰，打算从海上炮轰暴风城，而你也将直接攻向这位会长本人。",al={"迪菲亚任务线通向何处","迪菲亚故事如何结束","死亡矿井结局"}},["27471424"]={q="我是怎么来到西部荒野的？",a="你很可能受官员或哨兵岭友人的指派，从艾尔文森林沿路西行，跨过河上的桥梁来到这里。暴风城兵力捉襟见肘，无力抽调王室军队，格里安·斯托曼和当地农民急需能人相助的消息便传遍了邻近地区。无论你是响应求援而来，还是只是沿着国王大道寻找工作，你都踏入了一片几乎已被王国士兵遗弃的领土。",al={"如何来到这里","如何来到西部荒野","怎么会来到这里"}},["6324593c"]={q="我在西部荒野该做些什么？",a="你的首要任务是协助哨兵岭的人民军，击退正在扼杀这片土地的重重威胁。格里安·斯托曼需要志愿者清剿凶猛的野兽，摧毁在休耕农田间游荡的失控收割看守者，并击退河爪豺狼人。最重要的是，你要追查行踪隐秘的迪菲亚潜行者，找出他们的藏身之处，打破他们对西部荒野残存农庄的控制，让艰难度日的农户得以喘息。",al={"这里该做什么","在西部荒野做什么","为什么来这里"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="湿地",s="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙喉兽人、鱼人和豺狼人肆虐的潮湿荒野中的主要生命线。",h="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙...",kw={"巴拉丁海湾","龙喉氏族","丹奥加兹","丹莫德","格瑞姆巴托","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="米奈希尔港是联盟穿过无尽之海的主要深水门户，连接着东部王国与卡利姆多的远征前哨站。",["profession:Mining"]="瑟根石的山丘和洞穴深处蕴藏着丰富的矿脉，包括矮人矿工和工程师梦寐以求的稀有火岩矿石。",["race:Dwarf"]="对于矮人来说，湿地是一个苦乐参半的地方，这里铭记着丹莫德的陷落、格瑞姆巴托的古老悲剧，以及保卫麦格尼国王通往北方贸易路线的持续努力。"},sec={{t="水与废墟之地",b="湿地在巨石水坝高耸的悬崖下延伸开来，是一片寒冷、泥泞、终年笼罩在迷雾和阴沉灰暗天空下的广阔地带。这里曾经是矮人繁荣的定居点，如今却散布着沉没的石质废墟、潮湿的沼泽和险恶的泥潭。进入该地区的冒险者必须穿越狭窄的隘口，或是从洛克莫丹翻过丹奥加兹那道设有路障的峡谷，或是穿过萨多尔大桥的高耸拱门，从阿拉希高地进入。"},{t="格瑞姆巴托的伤痕",b="沼泽的东部边缘被格瑞姆巴托那阴沉的身影所笼罩，这里曾是蛮锤部族的据点。在三锤之战中被玷污后，它在第二次战争期间成为了龙喉氏族的坚固堡垒。当红龙军团从兽人的囚禁中挣脱出来后，它们炽热的复仇之火摧毁了兽人的军队，并将周围的山坡夷为平地。如今，红龙人守卫着龙喉大门以抵御一切入侵者，而龙喉氏族的残余势力则盘踞在零星的山间营地中，继续骚扰穿过沼泽的旅行者。"},{t="西海岸的港口",b="米奈希尔港坐落在巴拉丁海湾的边缘，是联盟在卡兹莫丹贸易和后勤的跳动心脏。这座坚固的港口以泰瑞纳斯·米奈希尔二世国王的名字命名，通过定期往返塞拉摩岛的运输船，以及经由南海镇前往奥伯丁的航线，将东部王国与遥远的卡利姆多连接起来。尽管它具有重要的战略军事意义，且拥有坚固的矮人建筑，但港口却时刻受到海岸鱼人、沼泽生物和那些专门掠夺穿行于礁石航道船只的海盗的威胁。"},{t="被围困的前线",b="湿地是一个多线作战的活跃战区。在极北之地，由术士邪恶的巴加拉斯领导的黑铁矮人炸毁了萨多尔大桥，并占领了丹莫德镇，切断了陆路补给线。与此同时，苔藓皮豺狼人在中央沼泽横行霸道，甚至威胁到了像绿色守卫者雷希耶尔这样的古老守护者。在流氓兽人小队、黑铁矮人渗透者和海岸沿线的受诅沉船之间，想要守住这片沼泽需要时刻保持警惕。"}},faq={{q="我该如何步行前往湿地？",a="联盟冒险者通常从洛克莫丹向北穿过丹奥加兹山口。部落旅行者从北方出发，可以越过阿拉希高地的萨多尔大桥。请务必小心，因为这两条通道都被龙喉兽人和黑铁矮人等敌对势力所控制。",al={"如何前往湿地","前往湿地的路径","跑向湿地"}},{q="米奈希尔港的船只去往哪里？",a="米奈希尔港的码头运营着两条前往卡利姆多的主要航线：一艘船停靠在希尔斯布莱德丘陵的南海镇，然后穿过无尽之海前往黑海岸的奥伯丁；另一艘则向南航行至尘泥沼泽的塞拉摩岛。",al={"米奈希尔港的船只","湿地的船去往何处"}},{q="格瑞姆巴托是什么，为什么有人守卫？",a="格瑞姆巴托是一座古老的矮人堡垒，在三锤之战后被遗弃，后来被龙喉氏族占据。第二次战争结束后，获得自由的红龙军团驱逐了兽人并封锁了这座大山。强大的红龙龙人守卫着龙喉大门，阻止任何人进入那座被诅咒的大厅。",al={"为什么格瑞姆巴托有龙","格瑞姆巴托的红龙","龙喉大门"}},{q="丹莫德发生了什么？",a="丹莫德曾是一座保卫萨多尔大桥的北部矮人据点。它最近遭到了由邪恶的巴加拉斯领导的黑铁矮人的袭击并被占领。幸存者在拉格·加玛森的带领下，在附近维持着一个处于交战状态的营地，并为夺回他们的城镇而战。",al={"谁摧毁了丹莫德","丹莫德废墟","丹莫德的黑铁矮人"}},{q="谁是绿色守卫者雷希耶尔？",a="雷希耶尔是一只居住在湿地绿带草地的古老沼泽兽。他寻求旅行者的帮助，以遏制侵略性的苔藓皮豺狼人的浪潮，并消灭患病的沼泽爬行者，从而让沼泽得以恢复。",al={"绿带草地","雷希耶尔与湿地","谁是绿色守卫者"}},{q="沼泽里所有的兽人是从哪里来的？",a="这些兽人属于龙喉氏族，他们在第二次战争期间最初在格瑞姆巴托加固了防御。在被获得自由的红龙军团摧毁后，幸存的兽人逃入了沼泽和山丘中，他们至今仍在那里发动袭击，骚扰公路和旅行者。",al={"为什么湿地有兽人","湿地的龙喉氏族","龙喉氏族在湿地"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="冬泉谷",s="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充满自然险境的土地，既庇护着蓝龙军团的残部，又要直面其南部高地上的恶魔腐化。",h="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充...",kw={"蓝龙","暗语峡谷","多诺瓦·雪山","永望镇","霜刃豹","冰盖草","凯斯利尔","麦索瑞尔","木喉","冬泉谷"},ang={["class:Druid"]="冬泉谷位于月光林地的高处，具有神圣的意义，这里是玛法里奥·怒风在第三次战争期间唤醒猛禽德鲁伊沉睡之地。",["faction:Alliance"]="联盟英雄们经常造访位于霜刀石的雷沃·霜翼，在严寒中不懈努力，只为赢得那久负盛名的冬泉霜刃豹坐骑的忠诚。",["profession:Herbalism"]="冬泉谷是冰盖草唯一的已知栖息地，这种极其重要的阿尔卑斯草药是高级炼金药剂配方中急需的原料，此外还有稀疏分布的山鼠草和罕见的黑莲花。",["profession:Mining"]="山谷中冰冷的岩脊和洞穴墙壁蕴藏着丰富的珍贵矿产，经常可以发现瑟银矿脉和富瑟银矿脉，以及罕见的真银矿石。",["race:NightElf"]="冬泉谷与精灵历史紧密相连，拥有猛禽德鲁伊沉睡了千年的兽穴、悲剧性的凯斯利尔废墟，以及在海加尔山之战中受损的诺达希尔裸露根须。"},sec={{t="永恒霜冻之地",b="冬泉谷坐落在高出周边荒野数千英尺的地方，终年笼罩在清冷的空气和无休止的暴风雪中。世界之树诺达希尔巨大的裸露根须如同高耸的木制拱门一样切开了积雪，这些根须在第三次战争的关键战役中被扭曲变形。虽然卡利姆多北部大部分地区以茂密的森林和温暖的气候为主，但冬泉谷却是一个拥有中海拔高山森林、岩石断崖和冰封湖泊的寂静之地，是强大的霜刃豹、奇美拉、雪人和厚皮冬泉熊的家园。"},{t="十字路口与前哨站",b="想要抵达这片高原，必须穿过木喉要塞中那些古老的雕凿通道，那里有未受腐化的熊怪把守，他们会严密审查任何从费伍德森林或月光林地经过的旅行者。在山谷的中心坐落着繁荣的贸易城镇永望镇，由热砂港管理。地精们敞开登记处欢迎联盟和部落的冒险者，这里成为了应对刺骨山寒的重要避风港，提供工程学、贸易和温暖的炉火。"},{t="古老的幽灵与蓝龙",b="在现代定居点出现前几个世纪，古老的精灵建造了湖畔城市凯斯利尔。在鲁莽的上层精灵法师打碎了被诅咒的辛玛洛水晶后，疯狂吞噬了他们，至今仍有不安的幻影在破碎的石柱和冰封的水域中徘徊。在更南边升起的是麦索瑞尔那洞窟纵横的高地，这是蓝龙军团在卡利姆多的传统据点。在这里，织法者玛里苟斯的子嗣们在守护者哈莱的监视下，看守着奥术流并对抗着当地的威胁。"},{t="峡谷中阴影的逼近",b="冬泉谷的宁静在其最南端的边界——暗语峡谷处被彻底打破。在那里，精英恶魔部队（第三次战争留下的残余军团）在崎岖的峡谷中爬行，阻挡着通往海加尔山顶峰的高处通路。与此同时，当地的冬泉熊怪已经屈服于污秽的腐化，这促使像多诺瓦·雪山这样的独立研究者在整个山谷的野生动物被吞噬之前，开始调查这种蔓延的污染。"}},faq={{q="我该如何前往冬泉谷？",a="旅行者必须穿过木喉要塞，这是一条位于费伍德森林东北部的地下隧道网。想要平安通过这些洞穴，需要赢得当地木喉熊怪的信任，否则他们会攻击任何被视为敌人的闯入者。一旦穿过东面的出口，冬泉谷的雪坡便会豁然开朗。",al={"前往冬泉谷","如何进入冬泉谷","冬泉谷入口","木喉要塞隧道"}},{q="谁管理着永望镇？",a="永望镇由地精贸易联合体热砂港管理。由于地精严格的利润导向和中立立场，只要访客不在镇内破坏和平，部落和联盟的旅行者都可以使用那里的飞行管理员、修理商、银行金库和贸易商品。",al={"谁控制永望镇","永望镇阵营","永望镇是否中立"}},{q="凯斯利尔湖中闹鬼的幽灵是什么？",a="它们是万年前居住在古城凯斯利尔的上层精灵暗夜精灵的灵魂。当他们的法师篡改了被窃的辛玛洛水晶后，水晶的破碎释放了一个灾难性的诅咒。几个世纪后，随后的高等精灵探险队也同样陷入了疯狂，注定要和他们的祖先一起在这片冰冷的废墟中徘徊。",al={"凯斯利尔湖幽灵","凯斯利尔废墟灵魂","凯斯利尔有哪些人"}},{q="为什么冬泉熊怪具有攻击性？",a="冬泉熊怪已经屈服于一种正在蔓延的、非自然的腐化，这种腐化导致他们的部族陷入了疯狂的敌对状态。虽然附近的木喉部族仍然保持着理智，但冬泉熊怪已经落入了黑暗的影响之下，这促使像多诺瓦·雪山这样的研究者去研究这些污染并清理他们的营地。",al={"为什么冬泉熊怪敌对","冬泉部族腐化","多诺瓦·雪山熊怪"}},{q="麦索瑞尔里住着什么？",a="麦索瑞尔是蓝龙军团在卡利姆多的主要巢穴和圣地。在它那洞穴纵横的尖塔深处，龙人、精英雏龙和古老的幼龙在守护者哈莱（守护巨龙玛里苟斯的配偶）的注视下，守护着强大的龙族遗物和奥术秘密。",al={"麦索瑞尔巨龙","什么是麦索瑞尔","冬泉谷蓝龙"}},{q="什么是暗语峡谷？",a="暗语峡谷是位于山谷最南端的一条危险峡谷，被第三次战争遗留下来的强大精英恶魔所占据。它是通往海加尔山高处的险峻小径上一道戒备森严的防线。",al={"暗语峡谷恶魔","暗语峡谷有什么","海加尔山之门冬泉谷"}},{q="我可以在这里训练或驯服霜刃豹吗？",a="在山谷最北端的霜刀石，暗夜精灵雷沃·霜翼负责照料当地的白豹。协助他获取补给并保护豹群的冒险者，或许能证明自己有资格学习饲养和骑乘霜刃豹的秘诀。",al={"霜刃豹坐骑","雷沃·霜翼霜刃豹","如何获得霜刃豹"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="泽风岛",s="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要接纳各处涌来的难民。",h="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要...",kw={"空艇","安维拉斯","元素位面","希洛卡斯","天裔","天空之墙","瓦拉纳尔","风石","泽风"},ang={["class:Shaman"]="泽风岛直接存在于风元素位面中，展示了当平衡元素之地的灵魂突然消失时，会发生怎样的景象。",["race:Skyborne"]="泽风岛是你的祖居地和初始之地，尽管它残留的美景之下掩盖着地形崩塌与元素力量消退的紧迫危机。"},sec={{t="云端位面",b="泽风岛是一块漂浮在天空之墙无尽风暴中的孤立陆地。世世代代以来，天裔与当地的风元素共同生活在此，这些元素帮助维持着岛屿漂浮所需的魔法流。然而，几个世纪前，这些元素守护者完全消失了。失去了它们的存在与庇护，支撑着这片土地的潜伏附魔已开始缓慢失效，导致泽风岛逐渐分崩离析，失去稳定。"},{t="断绝的视界",b="泽风岛并不是天裔在元素位面中居住的唯一庇护所。被称为Anvilas和Siroccas的姊妹岛屿也漂浮在天空之墙中，但在元素消失后，它们之间的通讯就断绝了。近来，来自这些崩解中的邻近陆地的难民设法抵达了泽风岛寻求庇护，他们带来了严峻的消息：其他岛屿正在他们的脚下彻底瓦解。"},{t="艾泽拉斯的门户",b="随着自身土地的缓慢衰败，泽风岛的天裔开始将目光投向天空之墙边界之外的艾泽拉斯。从瓦拉纳尔的空艇码头出发，飞船现已开始冒险建立起通往凡人位面的罕见生命线。这些航行将这片空灵的疆域直接连接到了艾泽拉斯的几处地点，包括奥特兰克山脉中的达拉然外围，以及莫高雷的观天者台地。"}},faq={{q="泽风岛位于何处？",a="泽风岛位于风元素位面天空之墙内，而非艾泽拉斯的表面。它漂浮在这片空灵疆域的永恒云层与风流之中。",al={"泽风岛位置","泽风在哪","泽风位于哪个位面"}},{q="为什么泽风岛正在崩塌？",a="这座岛屿依靠曾经与天裔共存的本地风元素而存在。几个世纪前，这些元素消失了，导致锚定和保护这座飞行岛屿的魔法基石随时间推移缓慢减弱并走向衰败。",al={"为什么泽风正在崩溃","泽风岛毁灭","垂死的岛屿"}},{q="安维拉斯和希洛卡斯是什么？",a="它们是天空之墙中同样居住着天裔的邻近浮空岛。当元素消失时，泽风岛与两者都失去了联系，而逃亡的难民现在报告称，安维拉斯和希洛卡斯都已经彻底湮灭。",al={"安维拉斯","西罗卡斯","其他天裔岛屿"}},{q="人们如何往返于泽风岛与艾泽拉斯之间？",a="天裔在瓦拉纳尔定居点运营着空艇码头。飞船从这些码头起飞，穿越位面边界前往艾泽拉斯，停靠在奥特兰克山脉的达拉然附近，以及莫高雷的观天者台地。",al={"如何离开泽风","泽风空艇","前往艾泽拉斯"}},{q="天裔是什么？",a="天裔是居住在泽风岛及其姊妹天空位面的居民。他们在天空之墙生活了世世代代，如今却因其飞行家园的束缚魔法消退，面临着家园缓慢毁灭的境地。",al={"天裔种族","谁住在泽风"}},{q="除了天裔，还有谁住在泽风岛上？",a="除了和平的村庄和来访的难民，岛上还受到当地强盗、穴居的夜爪洞穴生物，以及栖息在尖啸者巢穴和夜爪洞穴等地带野兽的困扰。",al={"泽风居民","泽风上的敌人"}}},fx={["1fd88046"]={q="泽风岛是什么地方？",a="泽风岛是一块高悬于天空之墙——风元素位面中的浮空陆地。数千年前，逃离埃雷萨拉斯迫害的暗夜精灵流亡者与当地风之灵达成交易；风之灵将岛屿托举至高空，以庇护他们。泽风岛是他们后裔——天裔的祖先圣所。",al={"泽风是什么","泽风岛简介","泽风岛信息"}},["7ea7c85c"]={q="泽风岛发生过什么？",a="高等精灵的祖先脱离了埃雷萨拉斯托塞德林王子的血腥统治后，泽风岛便升入了天空之墙。数千年来，天裔一直与空气元素和谐共处，但数百年前，那些元素守护者毫无解释地消失了。失去持续不断的魔法后，固定岛屿的石柱开始腐朽；邻近岛屿崩塌后，难民纷纷逃至此地，而内部各派系也在争夺日益匮乏的资源。",al={"泽风岛历史","泽风岛发生了什么","泽风岛背景故事"}},["70a3c6ae"]={q="泽风岛危险吗？",a="是的。除了岛屿本身日渐失稳、可能从高空坠落的迫近威胁外，元素守护者的消失也让这片土地陷入混乱。土匪营地、敌对野兽的巢穴，以及高阶会、塑风者和奥拉凯斯之间紧张的派系冲突，都使得离开设防定居点后的旅途危机四伏。",al={"泽风岛危险吗","泽风岛的威胁","泽风岛的危险"}},b4875d06={q="这座岛相对于艾泽拉斯其他地区位于何处？",a="泽风岛并非位于艾泽拉斯的地表，而是在天空之墙中漂浮。天空之墙是由泰坦造物打造、用于囚禁混乱空气元素的独立位面。泽风岛与下方凡世之间唯一的实体通道，是停靠在瓦拉纳尔、穿越边界前往达拉然和莫高雷等地的特制飞艇。",al={"泽风岛在艾泽拉斯的哪里","泽风岛在艾泽拉斯吗","泽风岛相对于艾泽拉斯的位置"}},["2c89f95d"]={q="奥拉凯斯人是谁？",a="奥拉凯斯是泽风岛上争夺主导权的派系之一，与高阶会和塑风者并立。随着固定岛屿的晶塔逐渐失效，生存变得愈发艰难，奥拉凯斯人正积极争夺霸权，以及对岛上剩余神秘资源的控制权。",al={"奥拉凯斯人是什么","奥拉凯斯派系","奥拉凯斯是谁"}},["6e14d755"]={q="我最终会离开这座岛吗？",a="会。泽风岛是你的家园，也是你开始接受训练的地方；飞艇会从瓦拉纳尔的空港出发，穿越位面裂隙前往艾泽拉斯大陆，直达奥特兰克山脉的达拉然和莫高雷的观天者台地。",al={"我会离开泽风岛吗","离开泽风岛","我们能去艾泽拉斯吗"}},["19470e71"]={q="我是怎么来到泽风岛的？",a="你出生于天裔族群，也就是居住在天空之墙——空气元素位面——高空浮岛上的辛多雷。数千年前，你的祖先逃离了埃雷萨拉斯王子托塞德林的清洗行动，并与风之灵缔结契约，由它们将这片圣所托举至天空。其他同源岛屿，如 安维拉斯 和 西洛卡斯，或已崩塌，或已渐渐远离，而泽风岛自始至终都是你的家。你将在此与自己的族人一同踏上旅程。",al={"我是怎么来到这里的","我是怎么到达泽风岛的","我为什么在这里醒来","我来自哪里"}},["5dae6f41"]={q="我在泽风岛应该做些什么？",a="你的家园正在你脚下崩塌。数百年前，仁慈的空气元素消失了，维系泽风岛的奥术晶塔也日渐失去力量。来自崩塌的外岛的难民涌入，而包括高阶会、塑风者和奥拉凯斯在内的敌对派系仍在为所剩无几的资源争斗。你必须帮助族人，平息内部威胁与野兽，协助稳定失效的魔法，并最终寻找一条通往艾泽拉斯的道路，以免岛屿坠毁。",al={"我在这里应该做什么","我在这里的目标是什么","我在泽风岛上做什么","我为什么在这里"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
